    if let Some(handle) = slot.as_ref() {
        let keys = handle.ledger.predicted_iter().map(|(key, _)| key);
        if keys.clone().next().is_some() {
            trace!("[Ledger] expect_free owner={} phase={} keys_held={:x?}", owner, phase, DebugIter(keys));
        }
    }
}

